/* nano5g bootstub — autoconf.h
 *
 * The vendored Rockbox sources include "autoconf.h", which in a real
 * Rockbox build is generated by configure. This hand-written replacement
 * keeps the values of a rockbox bootloader build for ipodnano5g and
 * carries ONLY the defines this build uses (each one verified: it is
 * referenced by the sources below, and the payload links byte-exact
 * without any of the removed generated defines).
 *
 *   ARCH / ARCH_M68K / ARCH_ARM / ARCH_MIPS   export/config.h core tests
 *   ARM_PROFILE_{CLASSIC,MICRO,APPLICATION}/ export/config.h core selection
 *   ARCH_PROFILE                             target/arm/system-arm.h
 *                                             (classic ARM core: ARM1176)
 *   ARCH_VERSION                               (ARMv6)
 *   ROCKBOX_LITTLE_ENDIAN                      include/rbendian.h
 *   ASSEMBLER_THREADS                          kernel/include/thread.h
 *                                             (asm/arm/thread-classic.h)
 *   ROCKBOX_DIR                                export/rbpaths.h — the boot
 *                                             directory "/.rockbox"
 *   ROCKBOX_BINARY_PATH, ROCKBOX_LIBRARY_PATH  export/rbpaths.h
 *
 * Notably absent (and absent on purpose): ROCKBOX_HAS_LOGF / LOGF_SERIAL
 * (no logf in this build), GCCNUM, HAVE_NOCROSSREFS_TO, DO_BOOTCHART.
 */
#ifndef __BUILD_AUTOCONF_H
#define __BUILD_AUTOCONF_H

#define ARCH_M68K 2
#define ARCH_ARM  3
#define ARCH_MIPS 4

#define ARCH               ARCH_ARM
#define ARCH_VERSION       6
#define ARM_PROFILE_CLASSIC 0
#define ARM_PROFILE_MICRO  1
#define ARM_PROFILE_APPLICATION 2
#define ARCH_PROFILE       ARM_PROFILE_CLASSIC

#define ROCKBOX_LITTLE_ENDIAN 1

#define ASSEMBLER_THREADS

#define ROCKBOX_DIR         "/.rockbox"
#define ROCKBOX_BINARY_PATH ""
#define ROCKBOX_LIBRARY_PATH ""

#endif /* __BUILD_AUTOCONF_H */
